dataSource.script:
return async function(config, ctx) {
  const apiUrl = String(config.apiUrl || '').trim();
  const token = String(config.token || '').trim();
  if (!apiUrl || !token) return { options: [] };

  const listUrl = apiUrl.replace(/\/$/, '').replace(/\/upload$/i, '') + '/storages';
  const res = await ctx.fetch(listUrl, {
    headers: {
      'Authorization': 'Bearer ' + token,
      'Accept': 'application/json'
    }
  });

  if (!res.ok) throw new Error('HTTP ' + res.status);
  const json = res.body;
  const items = Array.isArray(json.data) ? json.data : (json.data && json.data.items) || [];
  return {
    options: items.map(item => ({ label: item.name, value: String(item.id) }))
  };
}

uploader.script:
return async function(config, file, ctx) {
  if (!config.apiUrl) throw new Error('Missing apiUrl');

  const blob = await (await fetch(file.data)).blob();
  const fd = new FormData();
  fd.append('file', blob, file.name);
  fd.append('token', config.token);
  if (config.storageId) fd.append('storage_id', String(config.storageId));
  if (config.visibility) fd.append('visibility', String(config.visibility));
  if (config.optimize !== undefined) fd.append('optimize', String(config.optimize));

  const res = await ctx.fetch(config.apiUrl, {
    method: 'POST',
    body: fd
  });

  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = res.body;
  if (!data || !data.success) throw new Error((data && (data.message || data.msg)) || 'Upload failed');

  const url = data.url || (data.data && data.data.url);
  if (!url) throw new Error('Upload succeeded but no URL found');
  return url;
}
